     4		ChevronLeft,
     5		ChevronRight,
     6		ExternalLink,
     7	} from "lucide-react";
     8	import { type FC, type ReactNode, useState } from "react";
     9	import {
    10		type InteractionAction,
    11		InteractionCard,
    12		type InteractionView,
    13	} from "@/components/agents/interaction-card";
    14	import { Button } from "@/components/ui/button";
    15	import { cn, FILLED_BOX } from "@/lib/utils";
    16	import {
    17		isExternalHttpUrl,
    18		isLobuView,
    19		isServerAuthoredLobuView,
    20	} from "../_shared/view";
    21	import { type McpJsonNode, McpJsonTemplateView } from "./json-template-view";
    22	import { McpMarkdownText } from "./markdown-view";
    23	
    24	type UnknownRecord = Record<string, unknown>;
    25	
    26	function isRecord(value: unknown): value is UnknownRecord {
    27		return Boolean(value) && typeof value === "object" && !Array.isArray(value);
    28	}
    29	
    30	function humanize(value: string): string {
    31		return value
    32			.replace(/[_-]+/g, " ")
    33			.replace(/\b\w/g, (letter) => letter.toUpperCase());
    34	}
    35	
    36	function stringify(value: unknown): string {
    37		try {
    38			return JSON.stringify(value, null, 2);
    39		} catch {
    40			return String(value);
    41		}
    42	}
    43	
    44	function compactValue(value: unknown): string {
    45		if (value === null) return "null";
    46		if (value === undefined) return "—";
    47		if (typeof value === "string") return value;
    48		if (typeof value === "number" || typeof value === "boolean")
    49			return String(value);
    50		return stringify(value);
    51	}
    52	
    53	const Section: FC<{
    54		title: string;
    55		meta?: string;
    56		children: ReactNode;
    57		className?: string;
    58	}> = ({ title, meta, children, className }) => (
    59		<section className={cn(FILLED_BOX, "overflow-hidden", className)}>
    60			<header className="flex flex-wrap items-center justify-between gap-2 border-border/70 border-b px-3 py-2">
    61				<h2 className="font-medium text-sm">{title}</h2>
    62				{meta ? (
    63					<span className="text-muted-foreground text-xs">{meta}</span>
    64				) : null}
    65			</header>
    66			<div className="p-3">{children}</div>
    67		</section>
    68	);
    69	
    70	const LinkValue: FC<{ value: string; openLink: (href: string) => void }> = ({
    71		value,
    72		openLink,
    73	}) => {
    74		if (!isExternalHttpUrl(value))
    75			return <span className="break-words">{value}</span>;
    76		let label = value;
    77		try {
    78			const url = new URL(value);
    79			label = `${url.host}${url.pathname === "/" ? "" : url.pathname}`;
    80		} catch {
    81			// isExternalHttpUrl already validated it; retain the full value on an edge case.
    82		}
    83		return (
    84			<Button
    85				type="button"
    86				variant="ghost"
    87				size="sm"
    88				className="h-auto max-w-full justify-start px-1 py-0 text-left font-normal text-xs"
    89				onClick={() => openLink(value)}
    90			>
    91				<ExternalLink className="mr-1 h-3 w-3 shrink-0" />
    92				<span className="truncate">{label}</span>
    93			</Button>
    94		);
    95	};
    96	
    97	function looksLikeEvent(value: UnknownRecord): boolean {
    98		return (
    99			("semantic_type" in value || "payload_type" in value) &&
   100			("id" in value ||
   101				"title" in value ||
   102				"payload_text" in value ||
   103				"content" in value)
   104		);
   105	}
   106	
   107	function looksLikeEntity(value: UnknownRecord): boolean {
   108		return (
   109			"id" in value &&
   110			typeof value.name === "string" &&
   111			("entity_type" in value || "entity_type_name" in value || "type" in value)
   112		);
   113	}
   114	
   115	const EventView: FC<{
   116		event: UnknownRecord;
   117		openLink: (href: string) => void;
   118	}> = ({ event, openLink }) => {
   119		const title =
   120			typeof event.title === "string"
   121				? event.title
   122				: humanize(String(event.semantic_type ?? "Event"));
   123		const payloadType = String(event.payload_type ?? "text");
   124		const text =
   125			typeof event.payload_text === "string"
   126				? event.payload_text
   127				: typeof event.content === "string"
   128					? event.content
   129					: "";
   130		const sourceUrl =
   131			typeof event.source_url === "string" ? event.source_url : null;
   132		const template = isRecord(event.payload_template)
   133			? event.payload_template
   134			: null;
   135		const data = isRecord(event.payload_data) ? event.payload_data : {};
   136		const attachments = Array.isArray(event.attachments) ? event.attachments : [];
   137		const metadata = isRecord(event.metadata) ? event.metadata : null;
   138	
   139		return (
   140			<article className="rounded-md border border-border/70 bg-background/40 p-2.5">
   141				<div className="flex flex-wrap items-start justify-between gap-2">
   142					<div>
   143						<h3 className="font-medium text-sm">{title}</h3>
   144						<div className="text-muted-foreground text-[11px]">
   145							{humanize(String(event.semantic_type ?? "event"))}
   146							{event.id !== undefined ? ` · #${String(event.id)}` : ""}
   147						</div>
   148					</div>
   149					{sourceUrl && isExternalHttpUrl(sourceUrl) ? (
   150						<Button
   151							type="button"
   152							variant="ghost"
   153							size="sm"
   154							onClick={() => openLink(sourceUrl)}
   155						>
   156							<ExternalLink className="mr-1 h-3.5 w-3.5" />
   157							Source
   158						</Button>
   159					) : null}
   160				</div>
   161				<div className="mt-2">
   162					{payloadType === "json_template" && isRecord(template?.root) ? (
   163						<McpJsonTemplateView
   164							template={{ root: template.root as McpJsonNode }}
   165							data={data}
   166							openLink={openLink}
   167							actions={
   168								sourceUrl && isExternalHttpUrl(sourceUrl)
   169									? {
   170											openSource: () => openLink(sourceUrl),
   171											open_source: () => openLink(sourceUrl),
   172										}
   173									: undefined
   174							}
   175						/>
   176					) : payloadType === "markdown" && text ? (
   177						<McpMarkdownText text={text} openLink={openLink} />
   178					) : text ? (
   179						<p className="whitespace-pre-wrap break-words text-sm">{text}</p>
   180					) : Object.keys(data).length > 0 ? (
   181						<ValueView value={data} openLink={openLink} depth={1} />
   182					) : (
   183						<p className="text-muted-foreground text-xs">No event payload.</p>
   184					)}
   185				</div>
   186				{attachments.length > 0 ||
   187				(metadata && Object.keys(metadata).length > 0) ? (
   188					<details className="mt-2 text-xs">
   189						<summary className="cursor-pointer text-muted-foreground">
   190							Attachments and metadata
   191						</summary>
   192						<div className="mt-2 space-y-2">
   193							{attachments.length > 0 ? (
   194								<ValueView value={attachments} openLink={openLink} depth={1} />
   195							) : null}
   196							{metadata && Object.keys(metadata).length > 0 ? (
   197								<ValueView value={metadata} openLink={openLink} depth={1} />
   198							) : null}
   199						</div>
   200					</details>
   201				) : null}
   202			</article>
   203		);
   204	};
   205	
   206	const EntityView: FC<{
   207		entity: UnknownRecord;
   208		openLink: (href: string) => void;
   209	}> = ({ entity, openLink }) => {
   210		const label = humanize(
   211			String(
   212				entity.entity_type ?? entity.entity_type_name ?? entity.type ?? "Entity",
   213			),
   214		);
   215		const metadata = isRecord(entity.metadata) ? entity.metadata : null;
   216		const link = [entity.view_url, entity.url, entity.source_url].find(
   217			isExternalHttpUrl,
   218		);
   219		return (
   220			<article className="rounded-md border border-border/70 bg-background/40 p-2.5">
   221				<div className="flex items-start justify-between gap-2">
   222					<div>
   223						<div className="font-mono text-[10px] uppercase tracking-wide text-muted-foreground">
   224							{label}
   225						</div>
   226						<h3 className="font-medium text-sm">{String(entity.name)}</h3>
   227						<div className="text-muted-foreground text-[11px]">
   228							#{String(entity.id)}
   229						</div>
   230					</div>
   231					{link ? (
   232						<Button
   233							type="button"
   234							variant="ghost"
   235							size="sm"
   236							onClick={() => openLink(link)}
   237						>
   238							<ExternalLink className="mr-1 h-3.5 w-3.5" />
   239							Open
   240						</Button>
   241					) : null}
   242				</div>
   243				{metadata && Object.keys(metadata).length > 0 ? (
   244					<div className="mt-2">
   245						<ValueView value={metadata} openLink={openLink} depth={1} />
   246					</div>
   247				) : null}
   248			</article>
   249		);
   250	};
   251	
   252	const ValueView: FC<{
   253		value: unknown;
   254		openLink: (href: string) => void;
   255		depth?: number;
   256	}> = ({ value, openLink, depth = 0 }) => {
   257		if (typeof value === "string")
   258			return <LinkValue value={value} openLink={openLink} />;
   259		if (value === null || value === undefined || typeof value !== "object") {
   260			return <span className="break-words text-sm">{compactValue(value)}</span>;
   261		}
   262		if (depth >= 5) {
   263			return (
   264				<pre className="overflow-x-auto whitespace-pre-wrap text-xs">
   265					{stringify(value)}
   266				</pre>
   267			);
   268		}
   269		if (Array.isArray(value)) {
   270			if (value.length === 0)
   271				return <span className="text-muted-foreground text-xs">Empty</span>;
   272			const records = value.filter(isRecord);
   273			if (
   274				records.length === value.length &&
   275				!records.some(
   276					(record) => looksLikeEvent(record) || looksLikeEntity(record),
   277				)
   278			) {
   279				return <DataTable rows={records} openLink={openLink} />;
   280			}
   281			return (
   282				<div className="space-y-2">
   283					{value.slice(0, 100).map((item, index) => (
   284						// biome-ignore lint/suspicious/noArrayIndexKey: arbitrary result arrays may contain duplicate, identity-less values and are immutable here.
   285						<div key={`${index}:${compactValue(item).slice(0, 30)}`}>
   286							<ValueView value={item} openLink={openLink} depth={depth + 1} />
   287						</div>
   288					))}
   289					{value.length > 100 ? (
   290						<p className="text-muted-foreground text-xs">
   291							{value.length - 100} more items
   292						</p>
   293					) : null}
   294				</div>
   295			);
   296		}
   297		if (!isRecord(value))
   298			return <span className="text-sm">Unsupported value</span>;
   299		if (looksLikeEvent(value))
   300			return <EventView event={value} openLink={openLink} />;
   301		if (looksLikeEntity(value))
   302			return <EntityView entity={value} openLink={openLink} />;
   303		return (
   304			<dl className="grid gap-1.5">
   305				{Object.entries(value).map(([key, inner]) => (
   306					<div
   307						key={key}
   308						className="grid grid-cols-[minmax(6rem,0.35fr)_1fr] gap-2 text-xs"
   309					>
   310						<dt className="break-words font-medium text-muted-foreground">
   311							{humanize(key)}
   312						</dt>
   313						<dd className="min-w-0">
   314							<ValueView value={inner} openLink={openLink} depth={depth + 1} />
   315						</dd>
   316					</div>
   317				))}
   318			</dl>
   319		);
   320	};
   321	
   322	function DataTable({
   323		rows,
   324		columns,
   325		openLink,
   326	}: {
   327		rows: UnknownRecord[];
   328		columns?: Array<{ name: string; type?: string }>;
   329		openLink: (href: string) => void;
   330	}) {
   331		const [page, setPage] = useState(0);
   332		const pageSize = 10;
   333		const names =
   334			columns?.map((column) => column.name) ??
   335			[...new Set(rows.flatMap((row) => Object.keys(row)))].slice(0, 12);
   336		const pageCount = Math.max(1, Math.ceil(rows.length / pageSize));
   337		const visibleRows = rows.slice(page * pageSize, (page + 1) * pageSize);
   338		return (
   339			<div>
   340				<div className="overflow-x-auto">
   341					<table className="w-full border-collapse text-xs">
   342						<thead>
   343							<tr>
   344								{names.map((name) => (
   345									<th
   346										key={name}
   347										className="border border-border px-2 py-1.5 text-left font-medium"
   348									>
   349										{humanize(name)}
   350									</th>
   351								))}
   352							</tr>
