474					<div className="mb-2 flex items-center gap-1.5 text-xs">
475						{value.success === true ? (
476							<CheckCircle2 className="h-4 w-4 text-green-600" />
477						) : (
478							<AlertCircle className="h-4 w-4 text-destructive" />
479						)}
480						<span>{value.success === true ? "Completed" : "Failed"}</span>
481					</div>
482					{error ? (
483						<div className="mb-3 rounded-md border border-destructive/40 bg-destructive/10 p-2">
484							<div className="font-medium text-sm text-destructive">
485								{String(error.message ?? error.name ?? "SDK error")}
486							</div>
487							{error.code ? (
488								<div className="mt-1 text-muted-foreground text-xs">
489									{String(error.code)} ·{" "}
490									{error.retryable === true ? "retryable" : "not retryable"}
491								</div>
492							) : null}
493						</div>
494					) : null}
495					{value.return_value !== undefined ? (
496						<ValueView value={value.return_value} openLink={openLink} />
497					) : value.success === true ? (
498						<p className="text-muted-foreground text-xs">No return value.</p>
499					) : null}
500				</Section>
501				{sideEffects.length > 0 ? (
502					<Section
503						title="Dry-run side effects"
504						meta={`${sideEffects.length} skipped`}
505					>
506						<ValueView value={sideEffects} openLink={openLink} />
507					</Section>
508				) : null}
509				{logs.length > 0 || trace.length > 0 ? (
510					<details className={cn(FILLED_BOX, "px-3 py-2 text-xs")}>
511						<summary className="cursor-pointer font-medium">
512							Logs and SDK trace
513						</summary>
514						<div className="mt-2 space-y-2">
515							{logs.length > 0 ? (
516								<ValueView value={logs} openLink={openLink} />
517							) : null}
518							{trace.length > 0 ? (
519								<ValueView value={trace} openLink={openLink} />
520							) : null}
521						</div>
522					</details>
523				) : null}
524			</div>
525		);
