527	
528	function isSdkSearchResult(value: UnknownRecord): boolean {
529		return (
530			typeof value.query === "string" &&
531			typeof value.match_count === "number" &&
532			Array.isArray(value.results)
533		);
534	}
535	
536	const GenericResult: FC<{
537		value: UnknownRecord;
538		openLink: (href: string) => void;
539	}> = ({ value, openLink }) => {
540		if (isSdkSearchResult(value)) {
541			return (
542				<Section title="SDK documentation" meta={`${value.match_count} matches`}>
543					<div className="space-y-2">
544						{(value.results as unknown[]).map((result) => (
545							<pre
546								key={String(result)}
547								className="overflow-x-auto whitespace-pre-wrap rounded-md border border-border/70 bg-background/40 p-2 text-xs"
548							>
549								{String(result)}
550							</pre>
551						))}
552					</div>
553				</Section>
554			);
555		}
556		const title =
557			Array.isArray(value.content) || Array.isArray(value.matches)
558				? "Memory results"
559				: typeof value.semantic_type === "string" && typeof value.id === "number"
560					? "Memory saved"
561					: "Lobu result";
562		return (
563			<Section title={title}>
564				<ValueView value={value} openLink={openLink} />
565			</Section>
566		);
567	};
568	
569	export const McpResultView: FC<{
570		value: unknown;
571		onAction: (action: InteractionAction) => void;
572		openLink: (href: string) => void;
573		pendingId?: string | null;
574		resolvedId?: string | null;
575		allowSpaHostedViews?: boolean;
576	}> = ({
577		value,
578		onAction,
579		openLink,
580		pendingId,
581		resolvedId,
582		allowSpaHostedViews = false,
583	}) => {
584		const validView = allowSpaHostedViews
585			? isLobuView(value)
586			: isServerAuthoredLobuView(value);
587		if (validView) {
588			return (
589				<InteractionCard
590					view={value as InteractionView}
591					onAction={onAction}
592					pendingId={pendingId}
593					resolvedId={resolvedId}
594				/>
595			);
596		}
597		if (!isRecord(value)) {
598			return (
599				<Section title="Lobu result">
600					<ValueView value={value} openLink={openLink} />
601				</Section>
602			);
603		}
604		if (isSqlResult(value))
605			return <SqlResult value={value} openLink={openLink} />;
606		if (isSdkResult(value))
607			return <SdkResult value={value} openLink={openLink} />;
608		return <GenericResult value={value} openLink={openLink} />;
609	};

